def eventualSafeNodes(graph: List[List[int]]) -> List[int]:
    n = len(graph)
    rev = [[] for _ in range(n)]
    out = [len(g) for g in graph]
    for u in range(n):
        for v in graph[u]: rev[v].append(u)
    queue = deque(i for i in range(n) if out[i] == 0)
    safe = [False] * n
    while queue:
        v = queue.popleft()
        safe[v] = True
        for u in rev[v]:
            out[u] -= 1
            if out[u] == 0: queue.append(u)
    return [i for i in range(n) if safe[i]]

