int[] findRedundantConnection(int[][] edges) {
    int[] parent = new int[edges.length + 1];
    for (int i = 0; i < parent.length; i++) parent[i] = i;
    for (int[] e : edges) {
        int a = root(parent, e[0]), b = root(parent, e[1]);
        if (a == b) {
            return e;
        }
        parent[a] = b;
    }
    return new int[0];
}

int root(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

