    parent, owner = {}, {}

    def find(x: str) -> str:
        if parent[x] != x: parent[x] = find(parent[x])
        return parent[x]

    for acc in accounts:
        first = acc[1]
        for email in acc[1:]:
            parent.setdefault(email, email)
            owner[email] = acc[0]
            parent[find(email)] = find(first)
    groups = defaultdict(list)
    for email in parent: groups[find(email)].append(email)
    res = [[owner[emails[0]]] + sorted(emails) for emails in groups.values()]
